import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.C2TvIV46.js";const g=JSON.parse('{"title":"チームまたはプレイヤー対象","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/enums/team-or-player-target.md","filePath":"ja/language/enums/team-or-player-target.md"}'),s={name:"ja/language/enums/team-or-player-target.md"};function n(c,e,l,r,p,i){return t(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="チームまたはプレイヤー対象" tabindex="-1">チームまたはプレイヤー対象 <a class="header-anchor" href="#チームまたはプレイヤー対象" aria-label="Permalink to &quot;チームまたはプレイヤー対象&quot;">​</a></h1><p>特定のプレイヤー、特定のチーム、または全プレイヤーに適用するアクションのオペランド構文です。ManagedMegalo 文法では <code>&lt;team_or_player_target&gt;</code> として現れます。ワイヤ上では <code>s_team_or_player_target</code> として格納され、2 ビットの種類フィールド <code>e_action_team_or_player_target</code>（@blamnetwork/blf）を持ちます。</p><p><a href="/MegaloEvolved/beta/docs/ja/language/actions/set-score"><code>set_score</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/play-sound"><code>play_sound</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/actions/hud-post-message"><code>hud_post_message</code></a> で使います。<a href="/MegaloEvolved/beta/docs/ja/language/actions/submit-incident"><code>submit_incident</code></a> も、<code>&lt;cause_team_or_player&gt;</code> と <code>&lt;effect_team_or_player&gt;</code> オペランドに同じ基底型を使います。</p><h2 id="種類キーワード" tabindex="-1">種類キーワード <a class="header-anchor" href="#種類キーワード" aria-label="Permalink to &quot;種類キーワード&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キーワード</th><th>blf enum</th><th>意味</th></tr></thead><tbody><tr><td><code>team</code></td><td><code>team</code></td><td>特定のチーム — 続けて <a href="/MegaloEvolved/beta/docs/ja/language/references#team-designators">チーム参照</a></td></tr><tr><td><code>player</code></td><td><code>player</code></td><td>特定のプレイヤー — 続けて <a href="/MegaloEvolved/beta/docs/ja/language/references#reference-types">プレイヤー参照</a></td></tr><tr><td><code>everyone</code></td><td><code>all_players</code></td><td>セッション内の全プレイヤー</td></tr></tbody></table><p>スクリプトでは全プレイヤー種別を <code>everyone</code> と書きます。blf の enum 名は <code>all_players</code> です。</p><h2 id="構文" tabindex="-1">構文 <a class="header-anchor" href="#構文" aria-label="Permalink to &quot;構文&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>team &lt;team_ref&gt;</span></span>
<span class="line"><span>player &lt;player_ref&gt;</span></span>
<span class="line"><span>everyone</span></span></code></pre></div><p><code>team</code> と <code>player</code> の種類は、常に続くトークンに参照を含めます。<code>everyone</code> は単独で立ちます。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set_score add kill_points player killing_player</span></span>
<span class="line"><span class="megalo-text">action set_score add </span><span class="megalo-number">1</span><span class="megalo-text"> team attackers</span></span>
<span class="line"><span class="megalo-text">action play_sound everyone ctf</span></span>
<span class="line"><span class="megalo-text">action play_sound team defenders bone_cv_ph1_intro</span></span>
<span class="line"><span class="megalo-text">action hud_post_message everyone none </span><span class="megalo-string">&quot;Round started!&quot;</span></span>
<span class="line"><span class="megalo-text">action submit_incident game_start_slayer everyone everyone</span></span></code></pre></div><h2 id="audience-オペランドとは別物" tabindex="-1">audience オペランドとは別物 <a class="header-anchor" href="#audience-オペランドとは別物" aria-label="Permalink to &quot;audience オペランドとは別物&quot;">​</a></h2><p>いくつかのアクションは <strong>audience</strong> オペランド（<code>everyone</code>、<code>allies</code>、<code>enemies</code>、<code>player</code>、<code>team</code>、<code>no_one</code>）を取り、ナビポイント・境界・プログレスバー・ピックアップ規則を誰が見るかを絞り込みます。キーワードが一部重なっても、型は別物です（<code>c_player_filter_modifier</code>）。</p><table tabindex="0"><thead><tr><th>用途</th><th>オペランド型</th><th>例となるアクション</th></tr></thead><tbody><tr><td>スコア、サウンド、HUD メッセージ、インシデント</td><td>チームまたはプレイヤー対象</td><td><code>set_score</code>、<code>play_sound</code>、<code>hud_post_message</code>、<code>submit_incident</code></td></tr><tr><td>可視性とピックアップのフィルタ</td><td>Audience</td><td><code>navpoint_set_visible</code>、<code>boundary_set_visible</code>、<code>set_pickup_filter</code></td></tr></tbody></table><p>audience の一覧は <a href="/MegaloEvolved/beta/docs/ja/language/references#audience-references">参照 — Audience 参照</a> を参照してください。</p><h2 id="関連オペランド" tabindex="-1">関連オペランド <a class="header-anchor" href="#関連オペランド" aria-label="Permalink to &quot;関連オペランド&quot;">​</a></h2><p><a href="/MegaloEvolved/beta/docs/ja/language/actions/set-loadout"><code>set_loadout</code></a> の文法は同じ <code>team</code> / <code>player</code> 接頭辞パターンの <code>&lt;team_or_player&gt;</code> を使いますが、種類はそれら 2 つだけです（<code>everyone</code> なし）。</p>`,16)])])}const u=a(s,[["render",n]]);export{g as __pageData,u as default};
